"""Owner-facing, compact Intake and five-Content workflow for the existing Admin."""

INTAKE_WORKFLOW_CSS = r'''
.owner-intake-screen{padding:22px;background:#fff;border:1px solid #dfe6ee;border-radius:20px}
.owner-intake-screen h1{margin:.15rem 0;color:#132443}.owner-intake-open{min-height:52px;padding:12px 20px;margin-top:12px;background:#172e53;color:#fff;border:0;border-radius:12px;font-weight:850}
.owner-intake-dialog{width:min(690px,calc(100vw - 28px));max-height:min(94dvh,900px);margin:auto;padding:0;border:1px solid #e1e5eb;border-radius:26px;color:#151b28;box-shadow:0 22px 70px #172e5333;overflow:hidden}
.owner-intake-dialog::backdrop{background:#101b2e77;backdrop-filter:blur(3px)}.owner-intake-body{max-height:94dvh;overflow:auto;padding:25px 28px 24px}
.owner-intake-header{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;margin-bottom:20px;background:#fff;color:#152b4f;padding:0}.owner-intake-header h2{margin:0;color:#152b4f;font-size:1.65rem}.owner-intake-close{min-width:44px;min-height:44px;border-radius:50%;padding:6px;font-size:1.4rem}
.owner-intake-group{margin:17px 0 0}.owner-intake-group>label,.owner-intake-group>legend{display:block;margin:0 0 10px;color:#425064;font-size:1rem;font-weight:750}
.owner-intake-source{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.owner-intake-source button{min-height:104px;border:2px solid #e2e5e9;border-radius:17px;background:#fff;color:#151b28;font-size:1.04rem;font-weight:800}.owner-intake-source button span{display:block;margin-bottom:8px;font-size:1.5rem}.owner-intake-source button[aria-checked=true]{border-color:#4169ec;background:#eef3ff;color:#315ee0}
.owner-intake-group textarea{display:block;width:100%;min-height:145px;padding:15px;border:1px solid #d8dde5;border-radius:14px;resize:vertical;font:inherit;font-size:1rem;line-height:1.45}
.owner-intake-image-button{display:flex;align-items:center;justify-content:center;gap:10px;width:100%;min-height:94px;border:2px dashed #9aa9bf;border-radius:15px;background:#fff;color:#172e53;font-size:1.05rem;font-weight:750}
.owner-intake-count{margin:8px 0;color:#5f6f83;font-size:.9rem}.owner-intake-dialog .intake-media-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(112px,1fr));gap:8px;margin:10px 0}.owner-intake-dialog .intake-media-card{min-width:0;padding:7px;border:1px solid #e3e8ef;border-radius:12px;background:#f8faff}.owner-intake-dialog .intake-media-thumb{width:100%;height:82px;object-fit:cover;border-radius:8px}.owner-intake-dialog .intake-media-name{display:block;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:.75rem}.owner-intake-dialog .remove-media{min-height:34px;margin-top:6px;padding:5px 8px;font-size:.75rem}
.owner-intake-submit{width:100%;min-height:64px;margin-top:19px;background:#172e53;color:#fff;border:0;border-radius:15px;font-size:1.2rem;font-weight:900}.owner-intake-dialog #intake-msg{min-height:1.5em;margin:10px 0 0}.owner-intake-hidden-meta{display:none!important}
.owner-content-variants{display:grid;gap:12px}.owner-content-variant{padding:16px;border:1px solid #dce4ef;border-radius:16px;background:#fff}.owner-content-variant[data-selected=true]{border:2px solid #4169ec;background:#f5f8ff}.owner-content-variant>strong{display:block;margin-bottom:10px;color:#172e53;font-size:1.08rem}.owner-content-variant label{display:block;margin-top:9px;font-weight:700}.owner-content-variant input,.owner-content-variant textarea{width:100%;padding:11px;border:1px solid #d8dde5;border-radius:10px;font:inherit}.owner-content-variant textarea{min-height:150px;line-height:1.5}.owner-content-actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:10px}.owner-content-actions button{min-height:44px}.owner-content-secondary{margin-top:14px;padding:15px;border-radius:15px;background:#f4f7fb}
.owner-request-unverified{color:#9b3e12!important}.owner-review-technical{display:none!important}
@media(max-width:699px){.owner-intake-screen{padding:18px 15px}.owner-intake-dialog{position:fixed;inset:auto 0 0;width:100%;max-width:none;max-height:94dvh;margin:0;border-radius:22px 22px 0 0;border-bottom:0}.owner-intake-body{max-height:94dvh;padding:18px 16px calc(18px + env(safe-area-inset-bottom))}.owner-intake-header h2{font-size:1.45rem}.owner-intake-source{gap:8px}.owner-intake-source button{min-height:96px;font-size:.95rem}.owner-intake-submit{min-height:62px}.owner-intake-dialog .intake-media-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}
'''

INTAKE_WORKFLOW_SCRIPT = r'''<script>
(()=>{'use strict';
const $=s=>document.querySelector(s),form=$('#intake'),section=$('#intake-section');
if(!form||!section)return;
const source=form.elements.namedItem('source'),note=form.elements.namedItem('note'),sourceGroup=form.elements.namedItem('sourceGroup');
const mediaInput=$('#intake-media-input'),addMedia=$('#intake-add-media'),mediaCount=$('#intake-media-count'),mediaList=$('#intake-media-list'),save=$('#intake-save'),newIntake=$('#intake-new'),message=$('#intake-msg');
const preview=$('#intake-preview');
const dialog=document.createElement('dialog');dialog.id='owner-intake-dialog';dialog.className='owner-intake-dialog';dialog.setAttribute('aria-labelledby','owner-intake-title');
const body=document.createElement('div');body.className='owner-intake-body';
const header=document.createElement('header');header.className='owner-intake-header';const title=document.createElement('h2');title.id='owner-intake-title';title.textContent='Nhập sản phẩm mới';const close=document.createElement('button');close.type='button';close.className='secondary owner-intake-close';close.setAttribute('aria-label','Đóng cửa sổ nhập nguồn');close.textContent='×';close.onclick=()=>dialog.close();header.append(title,close);body.append(header);
const sourceGroupUi=document.createElement('fieldset');sourceGroupUi.className='owner-intake-group';sourceGroupUi.style.border='0';sourceGroupUi.style.padding='0';const sourceLegend=document.createElement('legend');sourceLegend.textContent='Nguồn sản phẩm';const sourceChoices=document.createElement('div');sourceChoices.className='owner-intake-source';sourceChoices.setAttribute('role','radiogroup');sourceChoices.setAttribute('aria-label','Nguồn sản phẩm');sourceGroupUi.append(sourceLegend,sourceChoices);
const options=[{value:'Cá nhân',label:'Trực tiếp',icon:'♙'},{value:'Zalo công ty',label:'Nhập từ Zalo',icon:'◉'}];
function setSource(value){source.value=value;for(const button of sourceChoices.querySelectorAll('button'))button.setAttribute('aria-checked',String(button.dataset.sourceValue===value))}
for(const option of options){const button=document.createElement('button');button.type='button';button.setAttribute('role','radio');button.dataset.sourceValue=option.value;const icon=document.createElement('span');icon.setAttribute('aria-hidden','true');icon.textContent=option.icon;button.append(icon,document.createTextNode(option.label));button.onclick=()=>setSource(option.value);sourceChoices.append(button)}
setSource(source.value==='Zalo công ty'?'Zalo công ty':'Cá nhân');
const info=document.createElement('section');info.className='owner-intake-group';const infoLabel=document.createElement('label');infoLabel.textContent='Thông tin sản phẩm';note.id='owner-intake-note';note.placeholder='Nhập hoặc dán nội dung…';infoLabel.htmlFor=note.id;info.append(infoLabel,note);const zaloHint=document.createElement('p');zaloHint.className='muted';zaloHint.textContent='Với nguồn Zalo, hãy tự dán nội dung bạn được phép sử dụng; chưa có kết nối Zalo tự động.';info.append(zaloHint);
const imageGroup=document.createElement('section');imageGroup.className='owner-intake-group';const imageLabel=document.createElement('label');imageLabel.textContent='Hình ảnh';addMedia.textContent='Thêm ảnh';addMedia.classList.add('owner-intake-image-button');mediaInput.accept='image/*';imageLabel.append(addMedia);imageGroup.append(imageLabel,mediaInput);mediaCount.classList.add('owner-intake-count');imageGroup.append(mediaCount,mediaList);
const hidden=document.createElement('div');hidden.className='owner-intake-hidden-meta';for(const name of ['sourceGroup','evidence_source_id','evidence_claim','evidence_rights']){const control=form.elements.namedItem(name);const label=control?.previousElementSibling;if(label)hidden.append(label);if(control)hidden.append(control)}hidden.append(source);
save.textContent='TẠO CONTENT';save.classList.add('owner-intake-submit');if(newIntake)newIntake.textContent='Bắt đầu sản phẩm mới · nguồn trước đã lưu';
body.append(sourceGroupUi,info,imageGroup,save);if(newIntake)body.append(newIntake);body.append(message,hidden);if(preview)body.append(preview);form.replaceChildren(body);dialog.append(form);document.body.append(dialog);
section.className='owner-intake-screen';section.replaceChildren();const kicker=document.createElement('p');kicker.className='kicker';kicker.textContent='NGUỒN';const screenTitle=document.createElement('h1');screenTitle.textContent='Nhập nguồn bất động sản';const explanation=document.createElement('p');explanation.className='muted';explanation.textContent='Tạo Intake một lần. Ảnh gốc được giữ nguyên; các xác nhận cần thiết sẽ hiện đúng lúc.';const openButton=document.createElement('button');openButton.type='button';openButton.className='owner-intake-open';openButton.textContent='＋  Nhập sản phẩm mới';section.append(kicker,screenTitle,explanation,openButton);
function openSheet(){if(window.navigateAdminScreen)window.navigateAdminScreen('intake');if(message){message.textContent='';message.className=''}if(!dialog.open)dialog.showModal();setTimeout(()=>note.focus({preventScroll:true}),30)}openButton.onclick=openSheet;
document.addEventListener('click',event=>{const link=event.target.closest?.('a[data-screen-link="intake"]');if(!link)return;event.preventDefault();event.stopImmediatePropagation();openSheet()},true);
dialog.addEventListener('close',()=>{if(message?.textContent&&/^Đã tạo 5/.test(message.textContent))message.textContent=''});
window.onContentBatchCreated=({review_id}={})=>{dialog.close();if(review_id&&window.navigateAdminScreen)window.navigateAdminScreen('content',{reviewId:review_id});const status=$('#content-studio [data-message]');if(status){status.className='ok';status.textContent='Đã tạo 5 bản nháp riêng tư. Chọn, chỉnh sửa hoặc sao chép; chưa duyệt, chưa đăng.'}window.scrollTo({top:0,behavior:'smooth'})};
const priorOpenMissing=window.openMissingFields;if(typeof priorOpenMissing==='function'){window.openMissingFields=(id,result,record)=>{priorOpenMissing(id,result,record);if(record?.invalidPrefillFields?.includes('address')){const panel=$('#missing-fields-known');if(panel)panel.textContent+=' Địa chỉ gợi ý trước đây không hợp lệ; hãy nhập vị trí thật từ nguồn.'}}}
const oldLoadReview=window.loadReview;
function isBadAddress(value){return ['ngay','hom nay','hom qua','ngay mai','ngay kia','hien tai','dang cap nhat','chua ro','khong ro','unknown','n a'].includes(String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').toLowerCase().trim().replace(/[ .,:;–—-]+/g,' '))}
function simplifyReview(){const host=$('#review-detail'),pkg=window.currentReviewPackage;if(!host)return;const studio=host.querySelector('#content-studio');const base=Array.from(host.children).find(node=>node.classList?.contains('item')&&node!==studio&&node.id!=='public-release');if(base){base.querySelectorAll('h4,pre,label,#review-field,#review-value,[data-edit-review]').forEach(node=>node.remove());const heading=base.querySelector('h3');if(heading)heading.textContent='Thông tin sản phẩm · '+(pkg?.state==='APPROVED'?'đã duyệt Gate A':pkg?.state==='STALE_REVIEW'?'cần kiểm tra lại':'chờ Owner duyệt');const facts=pkg?.candidate?.facts||{};let summary=base.querySelector('[data-owner-facts-summary]');if(!summary){summary=document.createElement('p');summary.dataset.ownerFactsSummary='true';heading?.after(summary)}const address=isBadAddress(facts.address)?'Cần nhập vị trí thật':(facts.address||'Chưa có vị trí');const price=facts.price_vnd_per_month?new Intl.NumberFormat('vi-VN').format(facts.price_vnd_per_month)+' đ/tháng':facts.price_vnd?new Intl.NumberFormat('vi-VN').format(facts.price_vnd)+' đ':'Chưa có giá';summary.textContent=[facts.title||'Bất động sản',facts.property_type||'',address,facts.area||'Chưa có diện tích',price].filter(Boolean).join(' · ');const approve=base.querySelector('[data-approve-review]');if(approve){approve.textContent='DUYỆT GATE A';const hasVariants=(pkg?.content_batches||[]).some(batch=>(batch.variants||[]).length===5);const selected=Boolean(pkg?.selected_content_variant_id);approve.disabled=approve.disabled||(hasVariants&&!selected);approve.title=hasVariants&&!selected?'Chọn một mẫu Content trước khi duyệt Gate A.':''}const reject=base.querySelector('[data-reject-review]');if(reject)reject.textContent='Từ chối nguồn'}
if(studio){const paras=Array.from(studio.querySelectorAll(':scope > p'));if(paras[0])paras[0].textContent='Năm bản nháp riêng tư. Chọn, chỉnh sửa hoặc sao chép mẫu; chưa duyệt và chưa đăng.';for(const p of paras.slice(1))p.remove();const mediaRecord=(window.intakeRecords||[]).find(row=>row.id===pkg?.candidate?.intake_id||row.contentReviewId===pkg?.review_id);let gallery=studio.querySelector('[data-owner-source-gallery]');if(gallery)gallery.remove();if(mediaRecord?.media?.length){gallery=document.createElement('div');gallery.dataset.ownerSourceGallery='true';gallery.className='owner-content-variants';gallery.setAttribute('aria-label','Ảnh nguồn được giữ trong Intake');for(const [index,item] of mediaRecord.media.entries()){const mediaId=item.mediaId||item.media_id;if(!mediaId)continue;const image=document.createElement('img');image.src='/api/intakes/'+encodeURIComponent(mediaRecord.id)+'/media/'+encodeURIComponent(mediaId);image.alt='Ảnh nguồn '+(index+1);image.loading='lazy';image.className='intake-media-thumb';gallery.append(image)}if(gallery.childElementCount){const label=document.createElement('p');label.className='muted';label.textContent=gallery.childElementCount+' ảnh nguồn được giữ riêng tư.';studio.insertBefore(label,studio.querySelector('[data-variants]'));studio.insertBefore(gallery,studio.querySelector('[data-variants]'))}}const evidence=studio.querySelector('#review-evidence');if(evidence){const text=evidence.querySelector('p.muted');if(text)text.textContent='Nguồn và quyền sử dụng nội dung phải được xác nhận theo đúng chứng từ. Việc này chưa duyệt quyền đăng ảnh.'}const cards=studio.querySelector('[data-variants]');if(cards){Array.from(cards.querySelectorAll(':scope > p.muted')).forEach(p=>p.remove());cards.classList.add('owner-content-variants');const variantCards=Array.from(cards.querySelectorAll(':scope > .item'));variantCards.forEach((card,index)=>{card.classList.add('owner-content-variant');const variantId=card.querySelector('[data-select]')?.closest('[data-variant-id]')?.dataset.variantId;const dataVariant=(pkg?.content_batches||[]).flatMap(batch=>batch.variants||[])[index];const selected=Boolean(dataVariant&&pkg?.selected_content_variant_id===dataVariant.content_variant_id);card.dataset.selected=String(selected);const b=card.querySelector('b');if(b)b.textContent='Mẫu '+(index+1)+' / 5'+(selected?' · Đã chọn':'');card.querySelectorAll('p.muted').forEach(p=>p.remove());const labels=card.querySelectorAll('label');if(labels[0])labels[0].textContent='Tiêu đề';if(labels[1])labels[1].textContent='Nội dung';const channels=card.querySelector('[data-channels]');if(channels){for(const button of Array.from(channels.querySelectorAll('button'))){if(!button.textContent.includes('Website'))button.remove();else{button.textContent='Duyệt mẫu cho Website';button.disabled=button.disabled||pkg?.state!=='APPROVED';button.title=pkg?.state==='APPROVED'?'':'Cần duyệt Gate A trước.'}}channels.classList.add('owner-content-actions')}card.querySelectorAll('details').forEach(node=>node.remove());const edit=card.querySelector('[data-edit]'),select=card.querySelector('[data-select]'),bodyField=card.querySelector('[data-body]');if(edit)edit.textContent='Lưu chỉnh sửa';if(select)select.textContent=selected?'Đã chọn mẫu':'Chọn mẫu này';if(select)select.classList.add('secondary');if(bodyField&&!card.querySelector('[data-copy-content]')){const copy=document.createElement('button');copy.type='button';copy.className='secondary';copy.dataset.copyContent='true';copy.textContent='Sao chép';copy.onclick=async()=>{try{await navigator.clipboard.writeText(bodyField.value);copy.textContent='Đã sao chép'}catch(_){bodyField.focus();bodyField.select();document.execCommand('copy');copy.textContent='Đã sao chép'}};select?.after(copy)}[edit,select].filter(Boolean).forEach(node=>node.classList.add('secondary'));if(edit)edit.classList.remove('secondary');const status=card.querySelector('[data-status]');if(status)status.textContent=selected?'Mẫu đã chọn. Gate A và đăng Website vẫn là bước riêng.':'Bản nháp riêng tư; chưa duyệt, chưa đăng.';card.querySelectorAll('[data-title],[data-body]').forEach(node=>node.setAttribute('aria-label',node.matches('[data-title]')?'Tiêu đề mẫu '+(index+1):'Nội dung mẫu '+(index+1)))});}}
const publicPanel=host.querySelector('#public-release');if(publicPanel){publicPanel.querySelector('[data-release-lineage]')?.remove();publicPanel.querySelector('[data-release-facts]')?.remove();const mediaSummary=publicPanel.querySelector('[data-release-media]');if(mediaSummary)mediaSummary.textContent='Chỉ ảnh có quyền sử dụng hợp lệ mới được đăng.';const preview=publicPanel.querySelector('[data-confirm-preview] summary');if(preview)preview.textContent='Xem trước tin và ảnh sẽ xuất hiện trên Website'}
const reviewSection=$('#review-section');if(reviewSection){const kicker=reviewSection.querySelector('.kicker'),heading=reviewSection.querySelector('h2'),note=reviewSection.querySelector('p.muted');if(kicker)kicker.textContent='CONTENT · RIÊNG TƯ';if(heading)heading.textContent='Chọn và duyệt Content';if(note)note.textContent='Chọn hoặc sửa một mẫu. Gate A duyệt dữ kiện; quyền ảnh và đăng Website là quyết định riêng.';const list=$('#reviews');if(list)list.hidden=true}
const queue=$('#queue-section');if(queue&&!queue.closest('details')){const details=document.createElement('details');details.className='owner-content-secondary';const summary=document.createElement('summary');summary.textContent='Nguồn đã lưu';details.append(summary);queue.before(details);details.append(queue)}
}
if(typeof oldLoadReview==='function'){window.loadReview=async id=>{await oldLoadReview(id);simplifyReview()}}
const oldCreate=window.createContent;if(typeof oldCreate==='function'){window.createContent=async(...args)=>{const result=await oldCreate(...args);return result}}
const work=$('[data-home-work]');if(work){const decorate=()=>{const rows=Array.isArray(window.intakeRecords)?window.intakeRecords.filter(row=>!(row.source==='TEST_ONLY'||[row.sourceGroup,row.note,row.clientBatchId].some(v=>String(v||'').includes('TEST_ONLY')))).slice(0,4):[];Array.from(work.querySelectorAll('.home-work-row')).forEach((card,index)=>{const record=rows[index];if(!record)return;const button=card.querySelector('.home-work-open');const detail=card.querySelector('.home-work-info small:last-child');if(record.contentAttemptState==='OUTCOME_UNVERIFIED'){if(button){button.disabled=true;button.textContent='Đối soát trước khi tiếp tục';button.onclick=null}card.classList.add('owner-request-unverified');if(detail)detail.textContent='Yêu cầu trước chưa có kết quả xác minh; chưa gửi lại.'}else if(record.contentBatchCount>0&&record.contentReviewId){if(button){button.disabled=false;button.textContent='XEM 5 CONTENT';button.onclick=async()=>{window.navigateAdminScreen?.('content',{intakeId:record.id,reviewId:record.contentReviewId});await window.loadReview(record.contentReviewId)}}}})};new MutationObserver(decorate).observe(work,{childList:true,subtree:true});setTimeout(decorate,0)}
if(new URLSearchParams(location.search).get('screen')==='intake')openSheet();
})();
</script>'''
